1	import { Client, type ClientChannel } from "ssh2";
2	
3	/**
4	 * READ-ONLY source auto-detection for the migration wizard.
5	 *
6	 * Given SSH credentials for a customer-specified SOURCE box, we open a single
7	 * password-authenticated SSH session and *look* at what is there — web roots,
8	 * home directories, database engines AND what is actually RUNNING (Docker
9	 * containers, listening ports, app processes and their working directories,
10	 * signature-bearing app dirs under /opt·/srv·/app, non-distro services) — so the
11	 * wizard can present a pre-checked "here's what we found" checklist instead of
12	 * making the customer type paths and DB names by hand. All of the running-app
13	 * discovery uses ONLY read-only probes: `docker ps`, `ss`/`netstat -lntp`, `ps`,
14	 * `readlink /proc/<pid>/cwd`, `du`, `[ -f ]`/`[ -d ]` tests and
15	 * `systemctl list-units` — no writes, installs or state changes, still fixed and
16	 * input-free (only constant shell globs the REMOTE shell expands), still capped
17	 * and timeout-bounded. Names/paths that come back are re-validated against the
18	 * same allowlists before any can be selected for transfer.
19	 *
20	 * SECURITY — the source is UNTRUSTED and customer-supplied, so this mirrors the
21	 * hardening in worker/migrate-real.ts:
22	 *
23	 *   1. The scan is strictly READ-ONLY. Every probe is a fixed, input-free shell
24	 *      script (directory globs are expanded by the REMOTE shell from constant
25	 *      patterns — no customer value is ever interpolated into it). We never
26	 *      write, install or modify anything on the source. Database listing reads
27	 *      its credentials file from `/dev/stdin`, so not even a temp file is
28	 *      written to the source.
29	 *
30	 *   2. SECRETS NEVER TOUCH A COMMAND STRING. The SSH password is handed to the
31	 *      ssh2 transport, never a shell. DB credentials are streamed into the far
32	 *      command's STDIN (a `[client]` defaults file / a `.pgpass` line consumed
33	 *      via `/dev/stdin`), never as an argv token.
34	 *
35	 *   3. STRICT ALLOWLIST VALIDATION. Host / port / SSH user / DB user are checked
36	 *      against shell-inert allowlists before use — we reject, never sanitize.
37	 *      Paths and DB names that come BACK from the source are re-validated against
38	 *      the same allowlist the real engine enforces; anything that doesn't match
39	 *      is dropped (it could not be migrated safely anyway).
40	 *
41	 *   4. Everything is timeout-bounded and size/count-capped.
42	 */
43	
44	// ---- Result shapes (no secrets ever) --------------------------------------
45	export type WebAppType = "wordpress" | "laravel" | "django" | "node" | "php" | "unknown";
46	
47	export type DetectedWebRoot = { path: string; sizeLabel: string; appType: WebAppType };
48	export type DetectedHome = { path: string; sizeLabel: string };
49	export type DetectedDatabase = { engine: "mysql" | "postgres"; name: string; sizeLabel: string };
50	export type DetectedEngine = {
51	  engine: "mysql" | "postgres";
52	  present: boolean;
53	  listening: boolean;
54	  listed: boolean; // did we successfully enumerate databases with the given creds?
55	};
56	
57	// The runtime that pointed us at a candidate app directory (or "unknown" when a
58	// directory scan found app signatures without a matching running process).
59	export type AppRuntime =
60	  | "node"
61	  | "python"
62	  | "java"
63	  | "ruby"
64	  | "php-fpm"
65	  | "pm2"
66	  | "next"
67	  | "dotnet"
68	  | "unknown";
69	// The on-disk signature that marks a directory as an app worth migrating.
70	export type AppDirSignature =
71	  | "wordpress"
72	  | "laravel"
73	  | "django"
74	  | "node"
75	  | "php"
76	  | "compose"
77	  | "python"
78	  | "git-repo"
79	  | "unknown";
80	
81	/** A candidate app directory discovered OUTSIDE the standard web roots — either a
82	 *  running process's cwd (#3) or a signature-bearing dir under /opt, /srv, /app… (#4). */
83	export type DetectedAppDir = {
84	  path: string;
85	  sizeLabel: string;
86	  runtime: AppRuntime;
87	  signature: AppDirSignature;
88	};
89	/** A running Docker container. `mounts` are the bind-mount host paths (the data to
90	 *  migrate); named volumes appear here too but are not absolute paths. */
91	export type DetectedContainer = {
92	  name: string;
93	  image: string;
94	  ports: string;
95	  mounts: string[];
96	};
97	/** A listening TCP socket + owning process, with a friendly role guess. Informational. */
98	export type DetectedPort = { port: number; proc: string; role: string };
99	/** A running non-distro systemd service — name only, as a hint. Informational. */
100	export type DetectedService = { name: string };
101	
102	export type ScanResult = {
103	  ok: boolean;
104	  webRoots: DetectedWebRoot[];
105	  homes: DetectedHome[];
106	  databases: DetectedDatabase[];
107	  engines: DetectedEngine[];
108	  // Running-app discovery (all read-only, informational except appDirs which are
109	  // migratable paths that get merged into the copy list, deduped against webRoots/homes).
110	  appDirs: DetectedAppDir[];
111	  containers: DetectedContainer[];
112	  ports: DetectedPort[];
113	  services: DetectedService[];
114	  notes: string[];
115	  // Read-only DB data-dir size estimate (bytes) — sum of the detected engines'
116	  // on-disk data dirs (/var/lib/mysql, /var/lib/postgresql). Lets the DB portion
117	  // count toward the migration total even though databases carry no per-DB size
118	  // unless the customer supplied DB creds. 0 when nothing detected / unreadable.
119	  dbSizeBytes?: number;
120	  // OS / CPU-architecture of the SOURCE, for the compatibility guardrail. Parsed
121	  // from /etc/os-release (NEVER sourced) + `uname -m`; display-only, re-validated.
122	  sourceOs?: { id: string; versionId: string; pretty: string } | null;
123	  sourceArch?: string | null;
124	  synthetic?: boolean;
125	};
126	
127	export type DetectInput = {
128	  host: string;
129	  port: number;
130	  user: string;
131	  password: string;
132	  /** Optional DB admin creds — only then can we enumerate database names/sizes. */
133	  dbUser?: string;
134	  dbPassword?: string;
135	};
136	
137	// ---- Timeouts / caps ------------------------------------------------------
138	const CONNECT_TIMEOUT_MS = 20_000;
139	const SCAN_TIMEOUT_MS = 75_000; // the big du/probe sweep
140	const DB_TIMEOUT_MS = 25_000;
141	const MAX_WEB_ROOTS = 40;
142	const MAX_HOMES = 40;
143	const MAX_DATABASES = 60;
144	const MAX_APP_DIRS = 40;
145	const MAX_CONTAINERS = 30;
146	const MAX_PORTS = 60;
147	const MAX_SERVICES = 30;
148	
149	// ---- Strict allowlist validators (mirror worker/migrate-real.ts) ----------
150	const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
151	const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
152	const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
153	const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
154	const DBUSER_RE = /^[A-Za-z0-9_]{1,64}$/;
155	const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/;
156	// MUST match IDENT_RE in worker/migrate-real.ts — only surface DB names the real
157	// transfer engine can actually migrate, so nothing selected here fails later.
158	const DBNAME_RE = /^[A-Za-z0-9_]{1,64}$/;
159	// Informational identifiers that come BACK from the source. These are never used
160	// in a shell or selected for transfer — only rendered as text — but we still keep
161	// them shell-inert and bounded so nothing weird flows through.
162	const CONTNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
163	const SVCNAME_RE = /^[A-Za-z0-9@][A-Za-z0-9@._-]{0,127}$/;
164	
165	/** Strip control chars, trim and bound the length of any free text from the source. */
166	function cleanText(s: string, max: number): string {
167	  // eslint-disable-next-line no-control-regex
168	  return (s ?? "").replace(/[\x00-\x1f\x7f]/g, "").trim().slice(0, max);
169	}
170	
171	// Well-known listening ports → a friendly role label for the "what's running" summary.
172	const PORT_ROLES: Record<number, string> = {
173	  21: "ftp",
174	  22: "ssh",
175	  25: "mail",
176	  80: "web",
177	  110: "mail",
178	  143: "mail",
179	  443: "web",
180	  465: "mail",
181	  587: "mail",
182	  993: "mail",
183	  3000: "app",
184	  3306: "mysql",
185	  4000: "app",
186	  5000: "app",
187	  5432: "postgres",
188	  5433: "postgres",
189	  5672: "rabbitmq",
190	  6379: "redis",
191	  8000: "app",
192	  8080: "app",
193	  8443: "web",
194	  9000: "app",
195	  9200: "elasticsearch",
196	  11211: "memcached",
197	  27017: "mongo",
198	};
199	function mapPortRole(p: number): string {
200	  return PORT_ROLES[p] ?? "other";
201	}
202	function mapRuntime(s: string): AppRuntime {
203	  switch (s) {
204	    case "node":
205	      return "node";
206	    case "python":
207	      return "python";
208	    case "java":
209	      return "java";
210	    case "ruby":
211	      return "ruby";
212	    case "phpfpm":
213	      return "php-fpm";
214	    case "pm2":
215	      return "pm2";
216	    case "next":
217	      return "next";
218	    case "dotnet":
219	      return "dotnet";
220	    default:
221	      return "unknown";
222	  }
223	}
224	function mapSignature(s: string): AppDirSignature {
225	  if (s === "gitrepo") return "git-repo";
226	  return (["wordpress", "laravel", "django", "node", "php", "compose", "python"] as AppDirSignature[]).includes(
227	    s as AppDirSignature
228	  )
229	    ? (s as AppDirSignature)
230	    : "unknown";
231	}
232	
233	function assert(cond: unknown, msg: string): asserts cond {
234	  if (!cond) throw new Error(msg);
235	}
236	function validHost(h: string): boolean {
237	  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
238	}
239	function validPath(p: string): boolean {
240	  return typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
241	}
242	
243	/** Collapse duplicate slashes and strip a trailing slash from a du-emitted path. */
244	function normalizeRemotePath(p: string): string {
245	  const collapsed = (p ?? "").replace(/\/{2,}/g, "/").replace(/\/+$/, "");
246	  return collapsed || "/";
247	}
248	
249	// ---- SSH plumbing (same shape as migrate-real.ts) -------------------------
250	function execRemote(
251	  conn: Client,
252	  cmd: string,
253	  timeoutMs: number
254	): Promise<{ code: number; stdout: string; stderr: string }> {
255	  return new Promise((resolve, reject) => {
256	    conn.exec(cmd, (err, stream: ClientChannel) => {
257	      if (err) return reject(err);
258	      let stdout = "";
259	      let stderr = "";
260	      const timer = setTimeout(() => {
261	        try {
262	          stream.close();
263	        } catch {
264	          /* ignore */
265	        }
266	        reject(new Error("remote command timed out"));
267	      }, timeoutMs);
268	      stream
269	        .on("close", (code: number) => {
270	          clearTimeout(timer);
271	          resolve({ code: code ?? 0, stdout, stderr });
272	        })
273	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
274	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
275	    });
276	  });
277	}
278	
279	/** Run a command, streaming `input` into its STDIN (secret goes here, never argv). */
280	function execRemoteInput(
281	  conn: Client,
282	  cmd: string,
283	  input: string,
284	  timeoutMs: number
285	): Promise<{ code: number; stdout: string; stderr: string }> {
286	  return new Promise((resolve, reject) => {
287	    conn.exec(cmd, (err, stream: ClientChannel) => {
288	      if (err) return reject(err);
289	      let stdout = "";
290	      let stderr = "";
291	      const timer = setTimeout(() => {
292	        try {
293	          stream.close();
294	        } catch {
295	          /* ignore */
296	        }
297	        reject(new Error("remote command timed out"));
298	      }, timeoutMs);
299	      stream
300	        .on("close", (code: number) => {
301	          clearTimeout(timer);
302	          resolve({ code: code ?? 0, stdout, stderr });
303	        })
304	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
305	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
306	      stream.end(input);
307	    });
308	  });
309	}
310	
311	function connectSource(input: DetectInput): Promise<Client> {
312	  return new Promise((resolve, reject) => {
313	    const conn = new Client();
314	    conn.on("ready", () => resolve(conn));
315	    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
316	    conn.connect({
317	      host: input.host,
318	      port: input.port,
319	      username: input.user,
320	      password: input.password,
321	      readyTimeout: CONNECT_TIMEOUT_MS,
322	      // Password-only: never offer a local key to the untrusted source host.
323	      tryKeyboard: false,
324	    });
325	  });
326	}
327	
328	// ---- Helpers --------------------------------------------------------------
329	function humanBytes(n: number): string {
330	  if (!Number.isFinite(n) || n <= 0) return "0 B";
331	  const units = ["B", "KB", "MB", "GB", "TB"];
332	  let i = 0;
333	  let v = n;
334	  while (v >= 1024 && i < units.length - 1) {
335	    v /= 1024;
336	    i++;
337	  }
338	  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`;
339	}
340	
341	/**
342	 * The read-only probe script. Deliberately input-free: the only variable parts
343	 * are constant shell globs expanded by the REMOTE shell, so there is no
344	 * injection surface. POSIX-sh only (works under `sh` or `bash`).
345	 */
346	// NOTE: authored as a plain string (not a template literal) so shell `${...}`
347	// parameter expansions can never collide with JS `${}` interpolation. Any
348	// trailing/duplicate slashes in emitted paths are normalized in JS below.
349	const SCAN_SCRIPT = [
350	  "export LC_ALL=C",
351	  'if command -v timeout >/dev/null 2>&1; then TO="timeout 25"; else TO=""; fi',
352	  "emit_web() {",
353	  "  d=$1",
354	  '  [ -d "$d" ] || return 0',
355	  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1)',
356	  '  [ -n "$sz" ] || sz=\'?\'',
357	  "  t=unknown",
358	  '  if [ -f "$d/wp-config.php" ]; then t=wordpress',
359	  '  elif [ -f "$d/artisan" ]; then t=laravel',
360	  '  elif [ -f "$d/manage.py" ]; then t=django',
361	  '  elif [ -f "$d/package.json" ]; then t=node',
362	  '  elif [ -f "$d/composer.json" ]; then t=php',
363	  "  else",
364	  '    for f in "$d"/*.php; do [ -e "$f" ] && { t=php; break; }; done',
365	  "  fi",
366	  "  printf 'WEB\\t%s\\t%s\\t%s\\n' \"$t\" \"$sz\" \"$d\"",
367	  "}",
368	  // Emit a candidate app directory OUTSIDE the web roots (a process cwd or a
369	  // signature-bearing dir). $1=runtime hint, $2=dir. Read-only: du + [ -f ] tests
370	  // only. seen_cwd de-dups within a shell to avoid repeated du on the same dir.
371	  "seen_cwd=' '",
372	  "emit_appdir() {",
373	  "  rt=$1; d=$2",
374	  '  [ -d "$d" ] || return 0',
375	  '  case "$d" in /|/usr|/usr/*|/bin|/sbin|/lib|/lib/*|/lib64*|/etc|/etc/*|/proc*|/sys*|/dev*|/run*|/tmp|/tmp/*|/var/lib/docker*|/snap*) return 0;; esac',
376	  '  case "$seen_cwd" in *" $d "*) return 0;; esac',
377	  '  seen_cwd="$seen_cwd$d "',
378	  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1); [ -n "$sz" ] || sz=\'?\'',
379	  "  sig=unknown",
380	  '  if [ -f "$d/wp-config.php" ]; then sig=wordpress',
381	  '  elif [ -f "$d/artisan" ]; then sig=laravel',
382	  '  elif [ -f "$d/manage.py" ]; then sig=django',
383	  '  elif [ -f "$d/docker-compose.yml" ] || [ -f "$d/docker-compose.yaml" ] || [ -f "$d/compose.yml" ] || [ -f "$d/compose.yaml" ]; then sig=compose',
384	  '  elif [ -f "$d/requirements.txt" ]; then sig=python',
385	  '  elif [ -f "$d/package.json" ]; then sig=node',
386	  '  elif [ -f "$d/composer.json" ]; then sig=php',
387	  '  elif [ -d "$d/.git" ]; then sig=gitrepo',
388	  "  fi",
389	  "  printf 'APPDIR\\t%s\\t%s\\t%s\\t%s\\n' \"$rt\" \"$sig\" \"$sz\" \"$d\"",
390	  "}",
391	  'for d in /var/www/html /usr/share/nginx/html /var/www /srv/www; do emit_web "$d"; done',
392	  'for d in /var/www/*/ /srv/www/*/ /home/*/public_html; do emit_web "$d"; done',
393	  "for d in /home/*/; do",
394	  '  [ -d "$d" ] || continue',
395	  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1); [ -n "$sz" ] || sz=\'?\'',
396	  "  printf 'HOME\\t%s\\t%s\\n' \"$sz\" \"$d\"",
397	  "done",
398	  "if [ -d /root ]; then",
399	  "  sz=$($TO du -shx /root 2>/dev/null | cut -f1); [ -n \"$sz\" ] || sz='?'",
400	  "  printf 'HOME\\t%s\\t%s\\n' \"$sz\" /root",
401	  "fi",
402	  "mp=0; ml=0; pp=0; pl=0",
403	  "{ command -v mysqld >/dev/null 2>&1 || command -v mariadbd >/dev/null 2>&1 || command -v mysql >/dev/null 2>&1 || [ -d /var/lib/mysql ]; } && mp=1",
404	  "{ command -v pg_dump >/dev/null 2>&1 || command -v psql >/dev/null 2>&1 || [ -d /var/lib/postgresql ]; } && pp=1",
405	  "ports=$( (ss -H -lnt 2>/dev/null || netstat -lnt 2>/dev/null) )",
406	  "printf '%s\\n' \"$ports\" | grep -q ':3306[^0-9]' && ml=1",
407	  "printf '%s\\n' \"$ports\" | grep -q ':5432[^0-9]' && pl=1",
408	  "printf 'ENGINE\\tmysql\\t%s\\t%s\\n' \"$mp\" \"$ml\"",
409	  "printf 'ENGINE\\tpostgres\\t%s\\t%s\\n' \"$pp\" \"$pl\"",
410	  // ---- DB data-dir size estimate (bytes). Only probed when the engine is
411	  // present. Constant paths, read-only `du -sbx`, $TO-bounded — no injection. --
412	  'if [ "$mp" = 1 ] && [ -d /var/lib/mysql ]; then',
413	  "  mb=$($TO du -sbx /var/lib/mysql 2>/dev/null | cut -f1); [ -n \"$mb\" ] || mb=0",
414	  "  printf 'DBSIZE\\tmysql\\t%s\\n' \"$mb\"",
415	  "fi",
416	  'if [ "$pp" = 1 ] && [ -d /var/lib/postgresql ]; then',
417	  "  pb=$($TO du -sbx /var/lib/postgresql 2>/dev/null | cut -f1); [ -n \"$pb\" ] || pb=0",
418	  "  printf 'DBSIZE\\tpostgres\\t%s\\n' \"$pb\"",
419	  "fi",
420	  // ---- OS / CPU architecture (read-only). /etc/os-release is GREPPED, never
421	  // sourced (the source is untrusted — sourcing could execute code); values are
422	  // re-validated + bounded in JS. `uname -m` for the arch. --
423	  'arch=$(uname -m 2>/dev/null); [ -n "$arch" ] || arch=unknown',
424	  "printf 'ARCH\\t%s\\n' \"$arch\"",
425	  "if [ -r /etc/os-release ]; then",
426	  "  grep -E '^(ID|VERSION_ID|PRETTY_NAME)=' /etc/os-release 2>/dev/null | head -n 20 | while IFS= read -r orl; do",
427	  "    printf 'OSREL\\t%s\\n' \"$orl\"",
428	  "  done",
429	  "fi",
430	  // ---- Running Docker containers (name/image/ports/mounts). Read-only `docker ps`
431	  // only; wrapped in $TO so an unresponsive daemon can't hang the probe. Cap 30. --
432	  "if command -v docker >/dev/null 2>&1; then",
433	  "  $TO docker ps --no-trunc --format '{{.Names}}|{{.Image}}|{{.Ports}}|{{.Mounts}}' 2>/dev/null | head -n 30 | while IFS= read -r dl; do",
434	  "    [ -n \"$dl\" ] && printf 'DOCKER\\t%s\\n' \"$dl\"",
435	  "  done",
436	  "fi",
437	  // ---- Listening TCP sockets + owning process (ss, fallback netstat). Read-only. --
438	  "lp=$( ($TO ss -H -lntp 2>/dev/null || $TO netstat -lntp 2>/dev/null) )",
439	  "printf '%s\\n' \"$lp\" | head -n 200 | while IFS= read -r pl; do",
440	  "  [ -n \"$pl\" ] && printf 'PORT\\t%s\\n' \"$pl\"",
441	  "done",
442	  // ---- App processes → their working directory (candidate app dirs). Read-only:
443	  // ps + readlink /proc/<pid>/cwd only; emit_appdir does the du/signature test. --
444	  "if command -v ps >/dev/null 2>&1; then",
445	  "  ps -eo pid=,comm= 2>/dev/null | head -n 400 | while read -r ppid pcomm; do",
446	  '    rt=""',
447	  '    case "$pcomm" in',
448	  "      node|nodejs) rt=node;;",
449	  "      python|python3|gunicorn|uvicorn|celery) rt=python;;",
450	  "      java) rt=java;;",
451	  "      ruby|puma|unicorn) rt=ruby;;",
452	  "      php-fpm*|php) rt=phpfpm;;",
453	  "      PM2*|pm2*) rt=pm2;;",
454	  "      next*|next-server*) rt=next;;",
455	  "      dotnet) rt=dotnet;;",
456	  "    esac",
457	  '    [ -n "$rt" ] || continue',
458	  '    cwd=$(readlink "/proc/$ppid/cwd" 2>/dev/null)',
459	  '    [ -n "$cwd" ] || continue',
460	  '    emit_appdir "$rt" "$cwd"',
461	  "  done",
462	  "fi",
463	  // ---- Signature-bearing app dirs under /opt, /srv, /app, home subdirs. Read-only. --
464	  "acount=0",
465	  "for d in /opt/*/ /srv/*/ /app /app/*/ /home/*/*/; do",
466	  '  [ -d "$d" ] || continue',
467	  '  case "$d" in /srv/www|/srv/www/*) continue;; esac',
468	  '  if [ -f "$d/package.json" ] || [ -f "$d/composer.json" ] || [ -f "$d/requirements.txt" ] || [ -f "$d/manage.py" ] || [ -f "$d/docker-compose.yml" ] || [ -f "$d/docker-compose.yaml" ] || [ -f "$d/compose.yml" ] || [ -f "$d/compose.yaml" ] || [ -d "$d/.git" ]; then',
469	  '    emit_appdir scan "$d"',
470	  '    acount=$((acount+1)); [ "$acount" -ge 60 ] && break',
471	  "  fi",
472	  "done",
473	  // ---- Running non-distro systemd services, name only, as hints. Read-only. --
474	  "if command -v systemctl >/dev/null 2>&1; then",
475	  "  $TO systemctl list-units --type=service --state=running --no-legend --plain 2>/dev/null | head -n 150 | while read -r unit rest; do",
476	  '    case "$unit" in',
477	  "      systemd*|dbus*|cron*|crond*|ssh*|sshd*|rsyslog*|syslog*|networkd*|resolved*|getty*|user@*|polkit*|accounts-daemon*|snapd*|multipathd*|udisks*|apparmor*|unattended*|packagekit*|chrony*|ntp*|thermald*|irqbalance*|atd*|acpid*) continue;;",
478	  "    esac",
479	  '    u=${unit%.service}',
480	  '    [ -n "$u" ] && printf \'SVC\\t%s\\n\' "$u"',
481	  "  done",
482	  "fi",
483	].join("\n");
