487	/** Parse a `du -sh`-style size label ("1.2G", "340M", "512K", "1.2 GB") into bytes. */
488	export function parseSizeLabel(label: string): number {
489	  const m = /^([\d.]+)\s*([KMGT]?)/i.exec(label.trim());
490	  if (!m) return 0;
491	  const n = parseFloat(m[1]);
492	  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
493	  return n * (mult[m[2].toUpperCase()] ?? 1);
494	}
