497	/**
498	 * SSH into the source (read-only) and return a structured inventory. Throws only
499	 * on a fatal connection/auth failure; a source that is reachable but has (say) no
500	 * readable DB creds still returns a useful partial result with notes.
501	 */
502	export async function detectSource(input: DetectInput): Promise<ScanResult> {
503	  assert(validHost(input.host), "source host is not a valid hostname or IP address");
504	  assert(Number.isInteger(input.port) && input.port >= 1 && input.port <= 65535, "source SSH port is out of range");
505	  assert(USER_RE.test(input.user), "source SSH username contains unsupported characters");
506	  assert(input.password && input.password.length > 0, "source SSH password is required");
507	
508	  const notes: string[] = [];
509	  const webRoots: DetectedWebRoot[] = [];
510	  const homes: DetectedHome[] = [];
511	  const databases: DetectedDatabase[] = [];
512	  const engines: DetectedEngine[] = [];
513	  const rawAppDirs: DetectedAppDir[] = [];
514	  const containers: DetectedContainer[] = [];
515	  const ports: DetectedPort[] = [];
516	  const services: DetectedService[] = [];
517	  const seenPort = new Set<string>();
518	  let dbSizeBytes = 0;
519	  let sourceArch: string | null = null;
520	  const osrel: { id?: string; versionId?: string; pretty?: string } = {};
521	
522	  const conn = await connectSource(input);
523	  try {
524	    // ---- 1. Filesystem + engine probe (fixed, input-free, read-only) ------
525	    const scan = await execRemote(conn, SCAN_SCRIPT, SCAN_TIMEOUT_MS);
526	    const engineState: Record<"mysql" | "postgres", { present: boolean; listening: boolean }> = {
527	      mysql: { present: false, listening: false },
528	      postgres: { present: false, listening: false },
529	    };
530	
531	    for (const raw of scan.stdout.split("\n")) {
532	      const line = raw.replace(/\r$/, "");
533	      if (!line) continue;
534	      const parts = line.split("\t");
535	      if (parts[0] === "WEB" && parts.length >= 4) {
536	        const appType = parts[1] as WebAppType;
537	        const sizeLabel = parts[2] || "?";
538	        const path = normalizeRemotePath(parts[3]);
539	        if (!validPath(path)) continue;
540	        if (webRoots.some((w) => w.path === path)) continue;
541	        webRoots.push({
542	          path,
543	          sizeLabel,
544	          appType: (["wordpress", "laravel", "django", "node", "php"] as WebAppType[]).includes(appType)
545	            ? appType
546	            : "unknown",
547	        });
548	      } else if (parts[0] === "HOME" && parts.length >= 3) {
549	        const sizeLabel = parts[1] || "?";
550	        const path = normalizeRemotePath(parts[2]);
551	        if (!validPath(path)) continue;
552	        if (homes.some((h) => h.path === path)) continue;
553	        homes.push({ path, sizeLabel });
554	      } else if (parts[0] === "ENGINE" && parts.length >= 4) {
555	        const eng = parts[1] === "postgres" ? "postgres" : "mysql";
556	        engineState[eng] = { present: parts[2] === "1", listening: parts[3] === "1" };
557	      } else if (parts[0] === "APPDIR" && parts.length >= 5) {
558	        const sizeLabel = parts[3] || "?";
559	        const path = normalizeRemotePath(parts[4]);
560	        if (!validPath(path)) continue; // candidate for TRANSFER — must pass the strict allowlist
561	        rawAppDirs.push({
562	          path,
563	          sizeLabel,
564	          runtime: mapRuntime(parts[1]),
565	          signature: mapSignature(parts[2]),
566	        });
567	      } else if (parts[0] === "DOCKER") {
568	        // Line body is "name|image|ports|mounts" (never contains a tab, so parts[1] holds it whole).
569	        if (containers.length >= MAX_CONTAINERS) continue;
570	        const seg = (parts.slice(1).join("\t")).split("|");
571	        const name = cleanText(seg[0] ?? "", 128);
572	        if (!CONTNAME_RE.test(name)) continue; // shell-inert display id
573	        if (containers.some((c) => c.name === name)) continue;
574	        const mounts = (seg[3] ?? "")
575	          .split(",")
576	          .map((m) => cleanText(m, 256))
577	          .filter((m) => m.length > 0)
578	          .slice(0, 12);
579	        containers.push({
580	          name,
581	          image: cleanText(seg[1] ?? "", 200),
582	          ports: cleanText(seg[2] ?? "", 200),
583	          mounts,
584	        });
585	      } else if (parts[0] === "PORT") {
586	        if (ports.length >= MAX_PORTS) continue;
587	        const body = parts.slice(1).join("\t").trim();
588	        const toks = body.split(/\s+/);
589	        if (toks.length < 4) continue;
590	        const local = toks[3]; // ss and netstat both put the local addr:port at index 3
591	        const pm = /:(\d{1,5})$/.exec(local);
592	        if (!pm) continue;
593	        const portNum = Number(pm[1]);
594	        if (!Number.isInteger(portNum) || portNum < 1 || portNum > 65535) continue;
595	        // Owning process: ss ⇒ users:(("name",…  ;  netstat ⇒ trailing "pid/name".
596	        let proc = "";
597	        const ssm = /users:\(\("([^"]+)"/.exec(body);
598	        if (ssm) proc = ssm[1];
599	        else {
600	          const nsm = /\s(\d+)\/([^\s]+)\s*$/.exec(body);
601	          if (nsm) proc = nsm[2];
602	        }
603	        proc = cleanText(proc, 64);
604	        const dedup = `${portNum}/${proc}`;
605	        if (seenPort.has(dedup)) continue;
606	        seenPort.add(dedup);
607	        ports.push({ port: portNum, proc, role: mapPortRole(portNum) });
608	      } else if (parts[0] === "DBSIZE" && parts.length >= 3) {
609	        const n = Number(parts[2]);
610	        if (Number.isFinite(n) && n > 0) dbSizeBytes += n;
611	      } else if (parts[0] === "ARCH" && parts.length >= 2) {
612	        const a = cleanText(parts[1], 32);
613	        if (/^[A-Za-z0-9_-]{1,32}$/.test(a)) sourceArch = a;
614	      } else if (parts[0] === "OSREL" && parts.length >= 2) {
615	        // "ID=debian" / VERSION_ID="12" / PRETTY_NAME="Debian GNU/Linux 12".
616	        const body = parts.slice(1).join("\t");
617	        const eq = body.indexOf("=");
618	        if (eq > 0) {
619	          const key = body.slice(0, eq).trim();
620	          const val = cleanText(body.slice(eq + 1).trim().replace(/^["']|["']$/g, ""), 128);
621	          if (key === "ID") osrel.id = val.toLowerCase().slice(0, 32);
622	          else if (key === "VERSION_ID") osrel.versionId = val.slice(0, 32);
623	          else if (key === "PRETTY_NAME") osrel.pretty = val;
624	        }
625	      } else if (parts[0] === "SVC" && parts.length >= 2) {
626	        if (services.length >= MAX_SERVICES) continue;
627	        const name = cleanText(parts[1], 128);
628	        if (!SVCNAME_RE.test(name)) continue;
629	        if (services.some((s) => s.name === name)) continue;
630	        services.push({ name });
631	      }
632	    }
633	
634	    // Prune web roots that are ancestors of another detected root (avoid copying
635	    // a parent AND its children — e.g. drop /var/www when /var/www/html exists).
636	    const pruned = webRoots.filter(
637	      (a) => !webRoots.some((b) => b.path !== a.path && b.path.startsWith(a.path + "/"))
638	    );
639	    webRoots.length = 0;
640	    webRoots.push(...pruned.slice(0, MAX_WEB_ROOTS));
641	    homes.splice(MAX_HOMES);
642	
643	    // Merge candidate app dirs into a migratable list, deduped against web roots /
644	    // home dirs (and each other) so a directory is never listed — or copied — twice.
645	    // A path clashes if it equals, contains, or is contained by an already-known path.
646	    const known = [...webRoots.map((w) => w.path), ...homes.map((h) => h.path)];
647	    const appDirs: DetectedAppDir[] = [];
648	    for (const a of rawAppDirs) {
649	      if (appDirs.length >= MAX_APP_DIRS) break;
650	      const clashesKnown = known.some(
651	        (p) => a.path === p || a.path.startsWith(p + "/") || p.startsWith(a.path + "/")
652	      );
653	      if (clashesKnown) continue;
654	      const clashesApp = appDirs.some(
655	        (b) => a.path === b.path || a.path.startsWith(b.path + "/") || b.path.startsWith(a.path + "/")
656	      );
657	      if (clashesApp) continue;
658	      appDirs.push(a);
659	    }
660	    appDirs.sort((x, y) => parseSizeLabel(y.sizeLabel) - parseSizeLabel(x.sizeLabel));
661	    if (appDirs.length > 0) {
662	      notes.push(
663	        `Found ${appDirs.length} app ${appDirs.length === 1 ? "directory" : "directories"} outside the standard web folders (from running processes / app files).`
664	      );
665	    }
666	    if (containers.length > 0) {
667	      notes.push(
668	        `Detected ${containers.length} running Docker ${containers.length === 1 ? "container" : "containers"} — we install Docker + Compose, copy their data and named volumes, and start any Compose project automatically on the new server.`
669	      );
670	    }
671	
672	    // ---- 2. Databases — only if the customer supplied DB creds ------------
673	    const hasSafePass =
674	      !!input.dbPassword && !input.dbPassword.includes("\n") && !input.dbPassword.includes("\r");
675	    if (input.dbPassword && !hasSafePass) {
676	      notes.push("Database password contains unsupported characters — databases were skipped.");
677	    }
678	
679	    for (const eng of ["mysql", "postgres"] as const) {
680	      const st = engineState[eng];
681	      const rec: DetectedEngine = { engine: eng, present: st.present, listening: st.listening, listed: false };
682	      if (st.present && hasSafePass) {
683	        const effUser = (input.dbUser && input.dbUser.trim()) || (eng === "mysql" ? "root" : "postgres");
684	        if (!DBUSER_RE.test(effUser)) {
685	          notes.push(`Database user "${effUser}" has unsupported characters — ${eng} databases were skipped.`);
686	        } else {
687	          try {
688	            const found =
689	              eng === "mysql"
690	                ? await listMysql(conn, effUser, input.dbPassword!)
691	                : await listPostgres(conn, effUser, input.dbPassword!);
692	            for (const d of found) {
693	              if (databases.length >= MAX_DATABASES) break;
694	              databases.push(d);
695	            }
696	            rec.listed = true;
697	          } catch (e: any) {
698	            notes.push(
699	              `${eng === "mysql" ? "MySQL" : "PostgreSQL"} is installed but we couldn't read its databases with those credentials — you can add databases manually.`
700	            );
701	          }
702	        }
703	      } else if (st.present && !input.dbPassword) {
704	        notes.push(
705	          `${eng === "mysql" ? "MySQL" : "PostgreSQL"} detected — all its databases are included automatically (no password needed; we dump them with root access on the old server).`
706	        );
707	      }
708	      engines.push(rec);
709	    }
710	
711	    databases.sort((a, b) => parseSizeLabel(b.sizeLabel) - parseSizeLabel(a.sizeLabel));
712	    ports.sort((a, b) => a.port - b.port);
713	
714	    const sourceOs =
715	      osrel.id || osrel.pretty || osrel.versionId
716	        ? { id: osrel.id ?? "", versionId: osrel.versionId ?? "", pretty: osrel.pretty ?? "" }
717	        : null;
718	
719	    return {
720	      ok: true,
721	      webRoots,
722	      homes,
723	      databases,
724	      engines,
725	      appDirs,
726	      containers,
727	      ports,
728	      services,
729	      notes,
730	      dbSizeBytes,
731	      sourceOs,
732	      sourceArch,
733	    };
734	  } finally {
735	    try {
736	      conn.end();
737	    } catch {
738	      /* best-effort */
739	    }
740	  }
741	}
