743	/** Enumerate MySQL/MariaDB schemas + sizes. Creds read from /dev/stdin (never argv). */
744	async function listMysql(conn: Client, user: string, pass: string): Promise<DetectedDatabase[]> {
745	  // `--defaults-extra-file=/dev/stdin` makes mysql read the [client] block from
746	  // the STDIN we stream below — the password never appears on the command line.
747	  const query =
748	    "SELECT table_schema, IFNULL(SUM(data_length+index_length),0) " +
749	    "FROM information_schema.tables GROUP BY table_schema;";
750	  const cnf = `[client]\nuser=${user}\npassword=${pass}\nhost=127.0.0.1\nprotocol=tcp\n`;
751	  const r = await execRemoteInput(
752	    conn,
753	    `mysql --defaults-extra-file=/dev/stdin -N -B -e ${shSingleQuote(query)}`,
754	    cnf,
755	    DB_TIMEOUT_MS
756	  );
757	  if (r.code !== 0) throw new Error(r.stderr.slice(0, 200) || `mysql exit ${r.code}`);
758	  const out: DetectedDatabase[] = [];
759	  for (const line of r.stdout.split("\n")) {
760	    const [name, bytes] = line.replace(/\r$/, "").split("\t");
761	    if (!name || SYSTEM_SCHEMAS.has(name.toLowerCase())) continue;
762	    if (!DBNAME_RE.test(name)) continue;
763	    out.push({ engine: "mysql", name, sizeLabel: humanBytes(Number(bytes) || 0) });
764	  }
765	  return out;
766	}
767	
768	/** Enumerate PostgreSQL databases + sizes. Creds read from /dev/stdin (.pgpass). */
769	async function listPostgres(conn: Client, user: string, pass: string): Promise<DetectedDatabase[]> {
770	  const query =
771	    "SELECT datname, pg_database_size(datname) FROM pg_database WHERE datistemplate = false;";
772	  const pgpass = `127.0.0.1:5432:*:${user}:${pass}\n`;
773	  const r = await execRemoteInput(
774	    conn,
775	    `PGPASSFILE=/dev/stdin psql -h 127.0.0.1 -U ${user} -w -A -t -F '\t' -c ${shSingleQuote(query)}`,
776	    pgpass,
777	    DB_TIMEOUT_MS
778	  );
779	  if (r.code !== 0) throw new Error(r.stderr.slice(0, 200) || `psql exit ${r.code}`);
780	  const out: DetectedDatabase[] = [];
781	  for (const line of r.stdout.split("\n")) {
782	    const [name, bytes] = line.replace(/\r$/, "").split("\t");
783	    if (!name || name === "postgres") continue;
784	    if (!DBNAME_RE.test(name)) continue;
785	    out.push({ engine: "postgres", name, sizeLabel: humanBytes(Number(bytes) || 0) });
786	  }
787	  return out;
788	}
