790	/**
791	 * Single-quote a FIXED, code-authored SQL string for the remote shell. The
792	 * inputs here are compile-time constants (never customer data), so this only
793	 * guards the literal `'` inside our own query text.
794	 */
795	function shSingleQuote(s: string): string {
796	  return `'${s.replace(/'/g, `'\\''`)}'`;
797	}
