77	type Items = {
78	  paths?: string[];
79	  // Legacy per-DB list (with encrypted password) — no longer used for dumping;
80	  // kept optional so old rows still type-check. Passwordless dumping uses dbEngines.
81	  databases?: { engine: string; name: string; user: string; passEnc?: string }[];
82	  dbEngines?: string[]; // which engines to dump via source root LOCAL auth
83	  dockerVolumes?: string[]; // named docker volumes to copy (/var/lib/docker/volumes/<n>/_data)
84	  composeDirs?: string[]; // compose project dirs → `docker compose up -d`
85	  verifyPorts?: number[]; // ports that should be listening on the target after bring-up
86	  hasContainers?: boolean; // Docker containers detected → install Docker Engine + compose
87	  webServers?: string[]; // "nginx" | "apache" to install + enable vhosts for
88	  runtimes?: string[]; // "nodejs" | "python3" to install
89	  totalBytes?: number; // trusted server-side total to migrate (bytes) for the pre-flight
90	  scan?: ScanSnapshot;
91	};
92	
93	// A single line item in the honest final summary.
94	export type MigrationStepResult = {
95	  step: string;
96	  // running  = verified running on the target
97	  // copied   = placed on the target but NOT verified running (may need a manual step)
98	  // failed   = attempted, failed (reason in detail) — did NOT fail the migration
99	  // skipped  = nothing to do
100	  status: "running" | "copied" | "failed" | "skipped";
101	  detail: string;
102	};
103	
104	export type RealMigrationSummary = {
105	  results: MigrationStepResult[];
106	  verifiedRunning: string[];
107	  needsAttention: string[];
108	};
109	
110	export type RealMigrationInput = {
111	  migration: MigrationRow;
112	  target: TargetServer | null;
113	  items: Items;
114	  report: ReportFn;
115	};
