117	// ---- Timeouts -------------------------------------------------------------
118	const CONNECT_TIMEOUT_MS = 20_000;
119	const SETUP_TIMEOUT_MS = 60_000; // small writes, checks
120	const INSTALL_TIMEOUT_MS = 10 * 60_000; // package installs (apt/dnf can be slow)
121	const TRANSFER_TIMEOUT_MS = Number(process.env.MIGRATE_EXEC_TIMEOUT_MS ?? 45 * 60_000); // rsync/dump/import
122	const GiB = 1024 ** 3;
123	
124	// ---- Strict allowlist validators (throw/reject on any violation) ----------
125	// Charsets below are deliberately shell-inert: no quotes, spaces, metachars or
126	// newlines. Validated values are therefore safe to interpolate into a command.
127	const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
128	const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
129	const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
130	const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
131	const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/; // absolute path, safe charset
132	// Docker volume name (docker's own charset) and systemd unit name — shell-inert.
133	const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
134	const SVCNAME_RE = /^[A-Za-z0-9@][A-Za-z0-9@._-]{0,127}$/;
135	
136	// Top-level system locations we refuse to overwrite on the target even if a
137	// (validated) path points at one — a lift-and-shift must never clobber the new
138	// server's own OS. Docker volumes/state are handled by their dedicated steps.
139	const UNSAFE_PREFIXES = [
140	  "/bin", "/sbin", "/usr", "/lib", "/lib64", "/etc/systemd", "/proc", "/sys",
141	  "/dev", "/run", "/boot", "/var/lib/docker",
142	];
143	const UNSAFE_EXACT = new Set(["/", "/etc", "/var", "/var/lib", "/usr", "/home", "/root/.ssh"]);
144	
145	function assert(cond: unknown, msg: string): asserts cond {
146	  if (!cond) throw new Error(msg);
147	}
148	
149	function validHost(h: string): boolean {
150	  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
151	}
152	
153	function validPath(p: string): boolean {
154	  return typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
155	}
156	
157	/** A validated path we are willing to rsync directly onto the target's real fs. */
158	function safeCopyTarget(p: string): boolean {
159	  if (!validPath(p)) return false;
160	  if (UNSAFE_EXACT.has(p)) return false;
161	  for (const pre of UNSAFE_PREFIXES) if (p === pre || p.startsWith(pre + "/")) return false;
162	  return true;
163	}
164	
165	/** dirname of a validated absolute path (both inputs/outputs are shell-inert). */
166	function parentDir(p: string): string {
167	  const i = p.lastIndexOf("/");
168	  return i <= 0 ? "/" : p.slice(0, i);
169	}
170	
171	// ---- SSH plumbing ---------------------------------------------------------
172	function execRemote(
173	  conn: Client,
174	  cmd: string,
175	  timeoutMs: number
176	): Promise<{ code: number; stdout: string; stderr: string }> {
177	  return new Promise((resolve, reject) => {
178	    conn.exec(cmd, (err, stream: ClientChannel) => {
179	      if (err) return reject(err);
180	      let stdout = "";
181	      let stderr = "";
182	      const timer = setTimeout(() => {
183	        try {
184	          stream.close();
185	        } catch {
186	          /* ignore */
187	        }
188	        reject(new Error("remote command timed out"));
189	      }, timeoutMs);
190	      stream
191	        .on("close", (code: number) => {
192	          clearTimeout(timer);
193	          resolve({ code: code ?? 0, stdout, stderr });
194	        })
195	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
196	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
197	    });
198	  });
199	}
200	
201	/** Write bytes to a remote file over SFTP with a fixed 0600 mode (no shell). */
202	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
203	  return new Promise((resolve, reject) => {
204	    const ws = sftp.createWriteStream(path, { mode: 0o600 });
205	    ws.on("close", () => resolve());
206	    ws.on("error", (e: Error) => reject(e));
207	    ws.end(Buffer.from(content, "utf8"));
208	  });
209	}
210	
211	function connectTarget(server: TargetServer): Promise<{ conn: Client; sftp: SFTPWrapper }> {
212	  return new Promise((resolve, reject) => {
213	    const target = connectionTarget(server as any);
214	    if (!target) return reject(new Error("target server is not reachable yet — connection details are pending"));
215	    const password = serverRootPassword(server);
216	    if (!password) return reject(new Error("target server has no root password on record"));
217	    const conn = new Client();
218	    conn.on("ready", () => {
219	      conn.sftp((err, sftp) => {
220	        if (err) return reject(err);
221	        resolve({ conn, sftp });
222	      });
223	    });
224	    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
225	    conn.connect({
226	      host: target.host,
227	      port: target.port,
228	      username: "root",
229	      password,
230	      readyTimeout: CONNECT_TIMEOUT_MS,
231	    });
232	  });
233	}
234	
235	// ---- Prerequisite install (FIXED allowlist — never source-supplied) -------
236	type PkgKey = "docker" | "mysql" | "postgresql" | "nginx" | "apache" | "nodejs" | "python3";
237	
238	// Command that succeeds iff the package's main binary is already present.
239	const PKG_CHECK: Record<PkgKey, string> = {
240	  docker: "command -v docker >/dev/null 2>&1",
241	  mysql: "command -v mysql >/dev/null 2>&1 || command -v mariadb >/dev/null 2>&1",
242	  postgresql: "command -v psql >/dev/null 2>&1",
243	  nginx: "command -v nginx >/dev/null 2>&1",
244	  apache: "command -v apache2 >/dev/null 2>&1 || command -v httpd >/dev/null 2>&1",
245	  nodejs: "command -v node >/dev/null 2>&1",
246	  python3: "command -v python3 >/dev/null 2>&1",
247	};
248	// Debian/Ubuntu (apt) package strings — the primary target for Nxeon servers.
249	const PKG_APT: Record<PkgKey, string> = {
250	  docker: "docker.io docker-compose-plugin",
251	  mysql: "mariadb-server mariadb-client",
252	  postgresql: "postgresql",
253	  nginx: "nginx",
254	  apache: "apache2",
255	  nodejs: "nodejs npm",
256	  python3: "python3 python3-pip",
257	};
258	// RHEL/Fedora (dnf/yum) fallback package strings.
259	const PKG_DNF: Record<PkgKey, string> = {
260	  docker: "docker docker-compose-plugin",
261	  mysql: "mariadb-server mariadb",
262	  postgresql: "postgresql-server postgresql",
263	  nginx: "nginx",
264	  apache: "httpd",
265	  nodejs: "nodejs npm",
266	  python3: "python3 python3-pip",
267	};
268	// A friendly label for the log/summary.
269	const PKG_LABEL: Record<PkgKey, string> = {
270	  docker: "Docker Engine + compose",
271	  mysql: "MySQL/MariaDB server",
272	  postgresql: "PostgreSQL server",
273	  nginx: "nginx",
274	  apache: "Apache",
275	  nodejs: "Node.js",
276	  python3: "Python 3 + pip",
277	};
278	
279	/**
280	 * Idempotently ensure each allowlisted package is present on the target. Runs
281	 * `apt-get update` once, then for each key: skip if the check passes, else try
282	 * apt → dnf → yum with the FIXED package string. Returns which were newly
283	 * installed / already present / failed. Never throws (best-effort per package).
284	 */
285	async function ensurePackages(
286	  conn: Client,
287	  keys: PkgKey[]
288	): Promise<{ key: PkgKey; ok: boolean; already: boolean; err?: string }[]> {
289	  const out: { key: PkgKey; ok: boolean; already: boolean; err?: string }[] = [];
290	  if (keys.length === 0) return out;
291	  // Refresh apt metadata once (best-effort; ignored on non-apt systems).
292	  await execRemote(conn, `apt-get update -y >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => {});
293	  for (const key of keys) {
294	    const already = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((r) => r.code === 0).catch(() => false);
295	    if (already) {
296	      out.push({ key, ok: true, already: true });
297	      continue;
298	    }
299	    // All three package strings are compile-time constants from the allowlist.
300	    const install =
301	      `DEBIAN_FRONTEND=noninteractive apt-get install -y ${PKG_APT[key]} ` +
302	      `|| dnf install -y ${PKG_DNF[key]} ` +
303	      `|| yum install -y ${PKG_DNF[key]}`;
304	    const r = await execRemote(conn, install, INSTALL_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
305	    const nowPresent = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
306	    if (nowPresent) {
307	      out.push({ key, ok: true, already: false });
308	    } else {
309	      const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
310	      out.push({ key, ok: false, already: false, err: tail || `install exit ${r.code}` });
311	    }
312	  }
313	  return out;
314	}
315	
316	// ---- Plan derivation (prefer explicit items, re-validate everything) ------
317	function derivePlan(items: Items) {
318	  const scan = items.scan ?? {};
319	
320	  // Engines to dump: explicit dbEngines, else engines the scan marked present.
321	  const engineSet = new Set<string>();
322	  for (const e of items.dbEngines ?? []) engineSet.add(e);
323	  if (engineSet.size === 0) for (const e of scan.engines ?? []) if (e?.present && e.engine) engineSet.add(e.engine);
324	  const dbEngines = [...engineSet].filter((e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres");
325	
326	  const dockerVolumes = [...new Set(items.dockerVolumes ?? [])].filter((v) => VOLNAME_RE.test(v)).slice(0, 60);
327	  const composeDirs = [...new Set(items.composeDirs ?? [])].filter((p) => validPath(p)).slice(0, 40);
328	  const verifyPorts = [...new Set((items.verifyPorts ?? []).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22))].slice(0, 60);
329	  const hasContainers = !!items.hasContainers || (scan.containers?.length ?? 0) > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
330	  const webServers = [...new Set(items.webServers ?? [])].filter((w): w is "nginx" | "apache" => w === "nginx" || w === "apache");
331	  const runtimes = [...new Set(items.runtimes ?? [])].filter((r): r is "nodejs" | "python3" => r === "nodejs" || r === "python3");
332	  const services = [...new Set((scan.services ?? []).map((s) => s?.name ?? "").filter((n) => SVCNAME_RE.test(n)))].slice(0, 30);
333	  const containers = (scan.containers ?? [])
334	    .map((c) => ({
335	      name: String(c?.name ?? ""),
336	      image: String(c?.image ?? ""),
337	      ports: String(c?.ports ?? ""),
338	      mounts: Array.isArray(c?.mounts) ? c!.mounts!.map((m) => String(m)) : [],
339	    }))
340	    .slice(0, 30);
341	
342	  const prereqs: PkgKey[] = [];
343	  if (dbEngines.includes("mysql")) prereqs.push("mysql");
344	  if (dbEngines.includes("postgres")) prereqs.push("postgresql");
345	  if (hasContainers) prereqs.push("docker");
346	  for (const w of webServers) prereqs.push(w === "nginx" ? "nginx" : "apache");
347	  for (const rt of runtimes) prereqs.push(rt);
348	
349	  return { dbEngines, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes, services, containers, prereqs };
350	}
