352	// ---------------------------------------------------------------------------
353	
354	/**
355	 * Perform a real lift-and-shift migration. Throws only on a FATAL setup error
356	 * (validation / target connect); every migration sub-step is best-effort and
357	 * records its outcome in the returned summary instead of aborting the run.
358	 */
359	export async function runRealMigration(input: RealMigrationInput): Promise<RealMigrationSummary> {
360	  const { migration, target, items, report } = input;
361	  assert(target, "target server row not found");
362	
363	  // ---- 1. Validate EVERY non-secret input up front (fail closed) ----------
364	  const host = migration.sourceHost;
365	  const port = migration.sourcePort;
366	  const user = migration.sourceUser;
367	  assert(validHost(host), "source host is not a valid hostname or IP address");
368	  assert(Number.isInteger(port) && port >= 1 && port <= 65535, "source SSH port is out of range");
369	  assert(USER_RE.test(user), "source username contains unsupported characters");
370	
371	  const rawPaths = (items.paths ?? []).map((p) => p.trim()).filter(Boolean);
372	  for (const p of rawPaths) assert(validPath(p), `unsupported file path: ${p}`);
373	  // Direct-to-real-path copy: refuse to overwrite the target's own OS locations.
374	  const paths = rawPaths.filter(safeCopyTarget);
375	
376	  const plan = derivePlan(items);
377	  for (const p of plan.composeDirs) assert(safeCopyTarget(p), `unsupported compose dir: ${p}`);
378	
379	  assert(paths.length || plan.dbEngines.length || plan.composeDirs.length || plan.dockerVolumes.length, "nothing selected to migrate");
380	
381	  // Root-vs-sudo prefix for privileged commands ON THE SOURCE (constant strings).
382	  const priv = user === "root" ? "" : "sudo -n ";
383	
384	  // ---- 2. Decrypt the ONE secret we still need (source SSH password) ------
385	  const sshPass = decryptSecret(migration.sourcePasswordEnc);
386	  assert(sshPass, "source SSH password is missing or could not be decrypted");
387	
388	  // ---- 3. Connect to the TARGET (our own server) --------------------------
389	  await report(6, "Connecting…", "Connecting to your Nxeon server to prepare the lift-and-shift.");
390	  const { conn, sftp } = await connectTarget(target!);
391	
392	  const work = `/root/nxeon-migrations/${migration.id}`;
393	  const passFile = `${work}/ssh.pass`;
394	  const knownHosts = `${work}/known_hosts`;
395	  const sshOpts =
396	    `-p ${port} -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile=${knownHosts} ` +
397	    `-o ConnectTimeout=25 -o PreferredAuthentications=password -o PubkeyAuthentication=no`;
398	  const srcSpec = `${user}@${host}`;
399	  // rsync pull from the source over the sshpass-driven ssh (used everywhere below).
400	  const rsyncPull = (remotePath: string, localParent: string) =>
401	    `sshpass -f ${passFile} rsync -az --numeric-ids --timeout=1200 -e 'ssh ${sshOpts}' ${srcSpec}:${remotePath} ${localParent}/`;
402	  // Run a fixed command ON THE SOURCE and capture its output on the target.
403	  const onSource = (cmd: string) => `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} '${cmd}'`;
404	
405	  const results: MigrationStepResult[] = [];
406	  const verifiedRunning: string[] = [];
407	  const needsAttention: string[] = [];
408	  const push = (r: MigrationStepResult) => {
409	    results.push(r);
410	    if (r.status === "running") verifiedRunning.push(r.step);
411	    else if (r.status === "copied" || r.status === "failed") needsAttention.push(`${r.step} — ${r.detail}`);
412	  };
413	
414	  try {
415	    // ---- 4. Prepare the target: transfer tools + work dir + secret file ----
416	    await report(10, "Preparing…", "Ensuring transfer tools (rsync, sshpass) are present on the target.");
417	    await execRemote(
418	      conn,
419	      `command -v rsync >/dev/null 2>&1 && command -v sshpass >/dev/null 2>&1 || ` +
420	        `{ (apt-get update -y && apt-get install -y rsync sshpass) || (dnf install -y rsync sshpass) || (yum install -y rsync sshpass); }`,
421	      INSTALL_TIMEOUT_MS
422	    );
423	    const tools = await execRemote(conn, `command -v rsync && command -v sshpass`, SETUP_TIMEOUT_MS);
424	    assert(tools.code === 0, "could not install rsync/sshpass on the target server");
425	
426	    await execRemote(
427	      conn,
428	      `mkdir -p ${work}/dumps && chmod 700 ${work} && touch ${knownHosts} && chmod 600 ${knownHosts}`,
429	      SETUP_TIMEOUT_MS
430	    );
431	    // Write the source SSH password to a 0600 file over SFTP (never a shell arg).
432	    await sftpWrite(sftp, passFile, sshPass);
433	
434	    // ---- 4b. STORAGE PRE-FLIGHT (defense in depth) ------------------------
435	    // Re-read the target's free disk right now and compare it to the planned
436	    // total. Abort early (before installing/copying anything) if it won't fit, so
437	    // we never fill the destination's disk. A probe we can't read is NOT a block
438	    // (matches the wizard's soft-warning behaviour) — we only stop when we can
439	    // positively confirm the data won't fit. This throw routes through the normal
440	    // migration-failure path (Migration → FAILED); it never marks the VM ERROR.
441	    const plannedBytes = Math.max(0, Number(items.totalBytes ?? 0));
442	    if (plannedBytes > 0) {
443	      await report(12, "Checking free space…", "Confirming the new server has room for everything selected.");
444	      const df = await execRemote(conn, `df -B1 --output=avail / 2>/dev/null | tail -n1`, SETUP_TIMEOUT_MS).catch(
445	        () => ({ code: 1, stdout: "", stderr: "" })
446	      );
447	      const avail = Number((df.stdout || "").trim().split("\n").pop()?.trim());
448	      if (Number.isFinite(avail) && avail > 0 && plannedBytes > avail) {
449	        const needGb = (plannedBytes / GiB).toFixed(1);
450	        const haveGb = (avail / GiB).toFixed(1);
451	        throw new Error(
452	          `Not enough free disk on the destination (need ${needGb} GB, have ${haveGb} GB) — add storage and retry.`
453	        );
454	      }
455	    }
456	
457	    // ---- 5. Install prerequisites on the target (fixed allowlist) ---------
458	    if (plan.prereqs.length) {
459	      await report(16, "Installing prerequisites…", `Preparing the target: ${plan.prereqs.map((k) => PKG_LABEL[k]).join(", ")}.`);
460	      const installed = await ensurePackages(conn, plan.prereqs);
461	      for (const r of installed) {
462	        if (r.ok) {
463	          push({ step: `Install ${PKG_LABEL[r.key]}`, status: "running", detail: r.already ? "already present" : "installed" });
464	          await report(18, "Installing prerequisites…", `  ${PKG_LABEL[r.key]}: ${r.already ? "already present" : "installed"}.`);
465	        } else {
466	          push({ step: `Install ${PKG_LABEL[r.key]}`, status: "failed", detail: r.err ?? "install failed" });
467	          await report(18, "Installing prerequisites…", `  ${PKG_LABEL[r.key]}: could not install — ${r.err ?? "unknown error"}.`);
468	        }
469	      }
470	      // Make sure DB engines + docker daemon are actually up before we use them.
471	      if (plan.dbEngines.includes("mysql"))
472	        await execRemote(conn, `systemctl enable --now mariadb 2>/dev/null || systemctl enable --now mysql 2>/dev/null || service mysql start 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
473	      if (plan.dbEngines.includes("postgres"))
474	        await execRemote(conn, `systemctl enable --now postgresql 2>/dev/null || service postgresql start 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
475	      if (plan.hasContainers)
476	        await execRemote(conn, `systemctl enable --now docker 2>/dev/null || service docker start 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
477	    }
478	
479	    // ---- 6. Files: rsync each selected path to the SAME path on target ----
480	    if (paths.length) {
481	      await report(28, "Copying files…", `Copying ${paths.length} path(s) from ${srcSpec} to the same locations on the new server.`);
482	      let idx = 0;
483	      let copied = 0;
484	      for (const p of paths) {
485	        idx++;
486	        const destParent = parentDir(p);
487	        await execRemote(conn, `mkdir -p ${destParent}`, SETUP_TIMEOUT_MS);
488	        const pct = 28 + Math.round((idx / paths.length) * 22); // 28 → 50
489	        await report(pct, "Copying files…", `  rsync ${p} → ${p}`);
490	        const r = await execRemote(conn, rsyncPull(p, destParent), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
491	        if (r.code === 0) {
492	          copied++;
493	        } else {
494	          const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
495	          push({ step: `Copy ${p}`, status: "failed", detail: tail || `rsync exit ${r.code}` });
496	          await report(pct, "Copying files…", `  copy failed for ${p}: ${tail || `rsync exit ${r.code}`}`);
497	        }
498	      }
499	      if (copied) push({ step: `Copy ${copied} folder(s) to their original paths`, status: "copied", detail: "files placed at the same paths on the new server" });
500	    }
501	
502	    // ---- 7. Named Docker volume data --------------------------------------
503	    if (plan.dockerVolumes.length) {
504	      await report(52, "Copying container data…", `Copying ${plan.dockerVolumes.length} named Docker volume(s).`);
505	      let ok = 0;
506	      for (const v of plan.dockerVolumes) {
507	        // Create the volume (idempotent), then rsync its _data into place.
508	        await execRemote(conn, `docker volume create ${v} >/dev/null 2>&1 || true`, SETUP_TIMEOUT_MS).catch(() => {});
509	        const dataDir = `/var/lib/docker/volumes/${v}/_data`;
510	        await execRemote(conn, `mkdir -p ${dataDir}`, SETUP_TIMEOUT_MS).catch(() => {});
