698	/** Where transient migration state (dumps) lands on the target, for the notice. */
699	export function migrationWorkDir(migrationId: string): string {
700	  return `/root/nxeon-migrations/${migration_id_safe(migrationId)}`;
701	}
702	
703	function migration_id_safe(id: string): string {
704	  return /^[A-Za-z0-9_-]{1,64}$/.test(id) ? id : "invalid";
705	}
