1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { encryptSecret } from "./crypto-box";
7	import { checkRateLimit } from "./rate-limit";
8	import { SANDBOX } from "./sandbox";
9	import { withServerSsh, exec, QUICK_TIMEOUT_MS } from "./ssh-exec";
10	import { detectSource, syntheticScan, parseSizeLabel, type ScanResult } from "../worker/migrate-detect";
11	
12	export type { ScanResult } from "../worker/migrate-detect";
13	
14	/**
15	 * VPS migration — pull a customer's files + databases from another provider's
16	 * VPS onto their new Nxeon server. The customer supplies SSH credentials for the
17	 * SOURCE box; we only ever verify ownership of the TARGET (Nxeon) server.
18	 *
19	 * All source secrets (the SSH password and each database password) are encrypted
20	 * at rest with the shared AES-256-GCM box in lib/crypto-box.ts (`encryptSecret`),
21	 * the SAME helper used for mailbox/BYOK secrets. They are CLEARED by the worker
22	 * (worker/migrate.ts) the moment the migration finishes — success or failure —
23	 * so a completed Migration row never retains usable credentials. Nothing here
24	 * ever returns a decrypted secret (or the ciphertext) to the client.
25	 *
26	 * The heavy lifting runs in the `MIGRATE` worker job; this module only validates
27	 * input, encrypts secrets, records the Migration row and enqueues the job.
28	 */
29	
30	// ---- Input shapes (mirrors the Migration.items Json) ------------------------
31	
32	export type CreateMigrationInput = {
33	  serverId: string; // target Nxeon server (must be owned by the caller)
34	  sourceHost: string; // FQDN or IP of the source VPS
35	  sourcePort?: number; // SSH port, default 22
36	  sourceUser?: string; // SSH user, default "root" (we use root's LOCAL auth to dump DBs)
37	  sourcePassword: string; // SSH password for the source box
38	  paths?: string[]; // file paths to copy from the source (to the same paths on the target)
39	  /**
40	   * Read-only auto-detection snapshot (from scanSource). Carries NO secrets. We
41	   * derive the whole lift-and-shift plan (which DB engines to dump passwordlessly,
42	   * Docker volumes/compose dirs, prerequisites to install, ports to verify) from
43	   * it, and store both the plan and the snapshot under Migration.items — reusing
44	   * the existing Json column rather than adding a schema field (another agent
45	   * owns the schema this wave).
46	   */
47	  scan?: ScanResult;
48	};
49	
50	// The passwordless lift-and-shift plan, derived from the scan + selected paths and
51	// carried through Migration.items (secret-free). The worker re-validates every
52	// value against strict shell-inert allowlists before it is used in a command.
53	type MigrationPlan = {
54	  dbEngines: ("mysql" | "postgres")[];
55	  dockerVolumes: string[];
56	  composeDirs: string[];
57	  verifyPorts: number[];
58	  hasContainers: boolean;
59	  webServers: ("nginx" | "apache")[];
60	  runtimes: ("nodejs" | "python3")[];
61	};
62	
63	// ---- Client-safe row shapes (NEVER include secrets) -------------------------
64	
65	export type MigrationDatabaseView = {
66	  engine: string;
67	  name: string;
68	  user: string;
69	};
70	
71	export type MigrationRow = {
72	  id: string;
73	  serverId: string;
74	  serverName: string | null;
75	  sourceHost: string;
76	  sourcePort: number;
77	  sourceUser: string;
78	  paths: string[];
79	  databases: MigrationDatabaseView[];
80	  status: string;
81	  progress: number;
82	  step: string | null;
83	  log: string | null;
84	  lastError: string | null;
85	  createdAt: string;
86	  finishedAt: string | null;
87	};
88	
89	// ---- Validation -------------------------------------------------------------
90	
91	// Hostname/FQDN (RFC-1123-ish) or IPv4 literal. Deliberately permissive on IPv6
92	// (a bracketed/colon form is accepted) — the worker's SSH layer does the final
93	// resolution; this only rejects obvious junk before we store anything.
94	const HOST_RE =
95	  /^(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?|\d{1,3}(?:\.\d{1,3}){3}|\[?[0-9a-fA-F:]+\]?)$/;
96	const DEFAULT_PATHS = ["/var/www", "/home"];
97	const MAX_PATHS = 40;
98	
99	function cleanPaths(paths: string[] | undefined): string[] {
100	  const list = (paths && paths.length ? paths : DEFAULT_PATHS)
101	    .map((p) => p.trim())
102	    .filter((p) => p.length > 0 && p.startsWith("/") && !p.includes("\0"));
103	  // De-dupe while preserving order.
104	  return [...new Set(list)].slice(0, MAX_PATHS);
105	}
106	
107	// Docker volume names are shell-inert (docker's own charset) — the worker
108	// re-validates, but we only ever store well-formed names.
109	const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
110	function isCopyableAbsPath(p: string): boolean {
111	  return typeof p === "string" && p.startsWith("/") && !p.includes("..") && p.length > 1;
112	}
113	
114	/**
115	 * Derive the passwordless lift-and-shift plan from the read-only scan and the set
116	 * of paths the customer chose to copy. Databases are auto-included whenever an
117	 * engine was detected (no password needed — the worker dumps via root's local
118	 * socket/peer auth); Docker/web/runtime prerequisites are inferred so the worker
119	 * can install them on the target. Everything here is secret-free.
120	 */
121	function derivePlan(scan: ScanResult | undefined, selectedPaths: string[]): MigrationPlan {
122	  const empty: MigrationPlan = {
123	    dbEngines: [],
124	    dockerVolumes: [],
125	    composeDirs: [],
126	    verifyPorts: [],
127	    hasContainers: false,
128	    webServers: [],
129	    runtimes: [],
130	  };
131	  if (!scan || !scan.ok) return empty;
132	  const pathSet = new Set(selectedPaths);
133	
134	  // Auto-include every detected engine (dump passwordlessly via root local auth).
135	  const dbEngines = [...new Set((scan.engines ?? []).filter((e) => e.present).map((e) => e.engine))].filter(
136	    (e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres"
137	  );
138	
139	  const containers = scan.containers ?? [];
140	  // Named Docker volumes = container mounts that are NOT absolute host paths.
141	  const dockerVolumes = [
142	    ...new Set(
143	      containers.flatMap((c) => c.mounts ?? []).filter((m) => !isCopyableAbsPath(m) && VOLNAME_RE.test(m))
144	    ),
145	  ].slice(0, 60);
146	
147	  // Compose project dirs among the app dirs the customer is actually copying.
148	  const composeDirs = [
149	    ...new Set((scan.appDirs ?? []).filter((a) => a.signature === "compose" && pathSet.has(a.path)).map((a) => a.path)),
150	  ].slice(0, 40);
151	
152	  const verifyPorts = [
153	    ...new Set((scan.ports ?? []).map((p) => p.port).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22)),
154	  ].slice(0, 60);
155	
156	  const hasContainers = containers.length > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
157	
158	  // Web servers: match the owning process/service names, else default to nginx
159	  // when web roots exist (the overwhelmingly common case).
160	  const procBlob = [
161	    ...(scan.ports ?? []).map((p) => p.proc || ""),
162	    ...(scan.services ?? []).map((s) => s.name || ""),
163	  ]
164	    .join(" ")
165	    .toLowerCase();
166	  const webServers: ("nginx" | "apache")[] = [];
167	  if (/nginx/.test(procBlob)) webServers.push("nginx");
168	  if (/apache|httpd/.test(procBlob)) webServers.push("apache");
169	  if (webServers.length === 0 && (scan.webRoots ?? []).length > 0) webServers.push("nginx");
170	
171	  // Runtimes: from running-app runtimes and listening-port owners. Conservative.
172	  const runtimeBlob = [
173	    ...(scan.appDirs ?? []).map((a) => a.runtime || ""),
174	    ...(scan.ports ?? []).map((p) => p.proc || ""),
175	  ]
176	    .join(" ")
177	    .toLowerCase();
178	  const runtimes: ("nodejs" | "python3")[] = [];
179	  if (/node|next|pm2/.test(runtimeBlob)) runtimes.push("nodejs");
180	  if (/python|gunicorn|uvicorn|celery/.test(runtimeBlob)) runtimes.push("python3");
181	
182	  return { dbEngines, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes };
183	}
