187	/**
188	 * Sum (in bytes) of the SELECTED migration items, plus the DB data-dir estimate
189	 * when a database engine was detected (databases are auto-included). Sizes come
190	 * from the read-only scan's human size labels; unknown-size items (custom folders,
191	 * Docker mounts) count as 0. Used both for the client storage panel and the
192	 * worker pre-flight — computed server-side here so the stored total is trusted.
193	 */
194	function selectedMigrationBytes(scan: ScanResult | undefined, selectedPaths: string[]): number {
195	  if (!scan || !scan.ok) return 0;
196	  const sizeByPath = new Map<string, number>();
197	  for (const w of scan.webRoots ?? []) sizeByPath.set(w.path, parseSizeLabel(w.sizeLabel));
198	  for (const h of scan.homes ?? []) sizeByPath.set(h.path, parseSizeLabel(h.sizeLabel));
199	  for (const a of scan.appDirs ?? []) sizeByPath.set(a.path, parseSizeLabel(a.sizeLabel));
200	  let total = 0;
201	  for (const p of selectedPaths) total += sizeByPath.get(p) ?? 0;
202	  // Databases are auto-included whenever an engine is present.
203	  const enginePresent = (scan.engines ?? []).some((e) => e.present);
204	  if (enginePresent) total += Math.max(0, scan.dbSizeBytes ?? 0);
205	  return Math.round(total);
206	}
