208	/** Parse ID / VERSION_ID / PRETTY_NAME lines from `/etc/os-release` (never sourced). */
209	function parseOsRelease(stdout: string): { id: string; versionId: string; pretty: string } | null {
210	  const o: Record<string, string> = {};
211	  for (const line of (stdout ?? "").split("\n")) {
212	    const m = /^(ID|VERSION_ID|PRETTY_NAME)=(.*)$/.exec(line.trim());
213	    if (!m) continue;
214	    o[m[1]] = m[2].trim().replace(/^["']|["']$/g, "").slice(0, 128);
215	  }
216	  if (!o.ID && !o.PRETTY_NAME && !o.VERSION_ID) return null;
217	  return {
218	    id: (o.ID ?? "").toLowerCase().slice(0, 32),
219	    versionId: (o.VERSION_ID ?? "").slice(0, 32),
220	    pretty: o.PRETTY_NAME ?? "",
221	  };
222	}
