224	async function ownedTargetServer(serverId: string) {
225	  const user = await requireUser();
226	  const server = await db.server.findUnique({ where: { id: serverId } });
227	  if (!server) throw new Error("Not found");
228	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
229	  return { user, server };
230	}
