232	function toRow(
233	  m: {
234	    id: string;
235	    serverId: string;
236	    sourceHost: string;
237	    sourcePort: number;
238	    sourceUser: string;
239	    items: unknown;
240	    status: string;
241	    progress: number;
242	    step: string | null;
243	    log: string | null;
244	    lastError: string | null;
245	    createdAt: Date;
246	    finishedAt: Date | null;
247	  },
248	  server: { hostname: string; label: string | null } | null
249	): MigrationRow {
250	  const items = (m.items ?? {}) as {
251	    paths?: string[];
252	    databases?: { engine?: string; name?: string; user?: string }[];
253	    dbEngines?: string[];
254	  };
255	  // Databases are now auto-included per detected engine (no per-DB list). For the
256	  // client view, surface one row per engine; fall back to any legacy per-DB list.
257	  const dbView: MigrationDatabaseView[] =
258	    Array.isArray(items.databases) && items.databases.length
259	      ? items.databases.map((d) => ({
260	          engine: String(d.engine ?? ""),
261	          name: String(d.name ?? ""),
262	          user: String(d.user ?? ""),
263	        }))
264	      : Array.isArray(items.dbEngines)
265	        ? items.dbEngines.map((e) => ({ engine: String(e), name: "All databases", user: "root" }))
266	        : [];
267	  return {
268	    id: m.id,
269	    serverId: m.serverId,
270	    // Migration has no Prisma relation to Server (serverId is a plain FK), so the
271	    // caller resolves the server row and passes it in.
272	    serverName: server ? server.label || server.hostname : null,
273	    sourceHost: m.sourceHost,
274	    sourcePort: m.sourcePort,
275	    sourceUser: m.sourceUser,
276	    paths: Array.isArray(items.paths) ? items.paths : [],
277	    // Never expose any DB secret — dbView carries only non-sensitive fields.
278	    databases: dbView,
279	    status: m.status,
280	    progress: m.progress,
281	    step: m.step,
282	    log: m.log,
283	    lastError: m.lastError,
284	    createdAt: m.createdAt.toISOString(),
285	    finishedAt: m.finishedAt ? m.finishedAt.toISOString() : null,
286	  };
287	}
