291	/**
292	 * Start a migration onto one of the caller's Nxeon servers. Verifies TARGET
293	 * ownership, validates the source connection details, encrypts every source
294	 * secret, writes the Migration row (PENDING) and enqueues a MIGRATE job. Returns
295	 * the new migration id; never returns any secret.
296	 */
297	export async function createMigration(
298	  input: CreateMigrationInput
299	): Promise<{ error?: string; id?: string }> {
300	  const { user, server } = await ownedTargetServer(input.serverId);
301	
302	  // Rate-limit: a few migrations per user per 10 minutes is plenty and stops
303	  // credential-stuffing the wizard against arbitrary source hosts.
304	  const rl = checkRateLimit(`migrate:create:${user.id}`, { max: 5, windowMs: 10 * 60 * 1000 });
305	  if (!rl.ok) {
306	    return { error: `Too many migrations started — please wait ${rl.retryAfterSec}s and try again.` };
307	  }
308	
309	  const host = (input.sourceHost ?? "").trim();
310	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
311	    return { error: "Enter a valid source host — an IP address or domain name." };
312	  }
313	
314	  const port = input.sourcePort ?? 22;
315	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
316	    return { error: "SSH port must be between 1 and 65535." };
317	  }
318	
319	  const sourceUser = (input.sourceUser ?? "root").trim();
320	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
321	    return { error: "Enter the SSH username on the source server." };
322	  }
323	
324	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
325	    return { error: "Enter the SSH password for the source server." };
326	  }
327	
328	  const paths = cleanPaths(input.paths);
329	
330	  // Derive the passwordless lift-and-shift plan from the scan + selected paths.
331	  // Databases are auto-included when an engine is detected — no DB password is
332	  // ever collected; the worker dumps via root's local socket/peer auth.
333	  const plan = derivePlan(input.scan, paths);
334	
335	  // Persist the (secret-free) detection snapshot alongside the plan so the
336	  // migration is traceable back to what auto-detection found. Reusing items
337	  // avoids a schema change (Migration.items is a Json column).
338	  const scanSnapshot =
339	    input.scan && input.scan.ok
340	      ? {
341	          webRoots: input.scan.webRoots?.slice(0, 40) ?? [],
342	          homes: input.scan.homes?.slice(0, 40) ?? [],
343	          databases: input.scan.databases?.slice(0, 60) ?? [],
344	          engines: input.scan.engines ?? [],
345	          // Running-app discovery — informational, secret-free, for traceability.
346	          appDirs: input.scan.appDirs?.slice(0, 40) ?? [],
347	          containers: input.scan.containers?.slice(0, 30) ?? [],
348	          ports: input.scan.ports?.slice(0, 60) ?? [],
349	          services: input.scan.services?.slice(0, 30) ?? [],
350	          // Storage-guardrail + compatibility inputs (secret-free, for traceability
351	          // and the worker pre-flight).
352	          dbSizeBytes: Math.max(0, input.scan.dbSizeBytes ?? 0),
353	          sourceOs: input.scan.sourceOs ?? null,
354	          sourceArch: input.scan.sourceArch ?? null,
355	          synthetic: !!input.scan.synthetic,
356	        }
357	      : undefined;
358	
359	  // Trusted server-side total of what will be migrated (bytes) — carried through
360	  // items so the worker's pre-flight guard can compare it to target free disk
361	  // without re-scanning. No schema change: Migration.items is a Json column.
362	  const totalBytes = selectedMigrationBytes(input.scan, paths);
363	
364	  const items = {
365	    paths,
366	    dbEngines: plan.dbEngines,
367	    dockerVolumes: plan.dockerVolumes,
368	    composeDirs: plan.composeDirs,
369	    verifyPorts: plan.verifyPorts,
370	    hasContainers: plan.hasContainers,
371	    webServers: plan.webServers,
372	    runtimes: plan.runtimes,
373	    totalBytes,
374	    ...(scanSnapshot ? { scan: scanSnapshot } : {}),
375	  };
376	
377	  const migration = await db.migration.create({
378	    data: {
379	      userId: user.id,
380	      serverId: server.id,
381	      sourceHost: host,
382	      sourcePort: port,
383	      sourceUser,
384	      sourcePasswordEnc: encryptSecret(input.sourcePassword),
385	      items,
386	      status: "PENDING",
387	      progress: 0,
388	      step: "Queued",
389	    },
390	  });
391	
392	  // Enqueue the worker job. serverId ties the job to the target (cascade delete +
393	  // traceability); the handler loads everything else from payload.migrationId.
394	  await db.job.create({
395	    data: {
396	      type: "MIGRATE",
397	      serverId: server.id,
398	      payload: { migrationId: migration.id },
399	    },
400	  });
401	
402	  await db.auditLog.create({
403	    data: {
404	      userId: user.id,
405	      action: "migration.create",
406	      detail: `${migration.id} ${sourceUser}@${host}:${port} -> ${server.hostname} (${paths.length} paths, ${plan.dbEngines.length} db engine(s), ${plan.composeDirs.length} compose)`,
407	    },
408	  });
409	
410	  revalidatePath("/dashboard/migrate");
411	  return { id: migration.id };
412	}
