414	/**
415	 * READ-ONLY auto-detection of a source box for the beginner wizard. Verifies the
416	 * caller owns the TARGET server (authz + a stricter rate limit than create),
417	 * validates the source connection details, then SSHes into the source and
418	 * inventories web roots / home directories / databases — never writing anything
419	 * on the source and never persisting the supplied credentials.
420	 *
421	 * The plaintext SSH/DB passwords are used in-memory for this one call only and
422	 * are NOT stored anywhere; the client re-supplies them to createMigration once
423	 * the customer confirms what to move. Returns a secret-free ScanResult.
424	 *
425	 * In SANDBOX (staging) this returns realistic SYNTHETIC results and never opens
426	 * a real SSH connection, so staging stays fully self-contained.
427	 */
428	export async function scanSource(input: {
429	  serverId: string;
430	  sourceHost: string;
431	  sourcePort?: number;
432	  sourceUser?: string;
433	  sourcePassword: string;
434	  dbUser?: string;
435	  dbPassword?: string;
436	}): Promise<{ error?: string; scan?: ScanResult }> {
437	  const { user } = await ownedTargetServer(input.serverId);
438	
439	  // Scanning SSHes into an arbitrary customer-named host, so throttle it harder
440	  // than migration creation to stop the wizard being used to probe hosts.
441	  const rl = checkRateLimit(`migrate:scan:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
442	  if (!rl.ok) {
443	    return { error: `Too many scans — please wait ${rl.retryAfterSec}s and try again.` };
444	  }
445	
446	  const host = (input.sourceHost ?? "").trim();
447	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
448	    return { error: "Enter a valid source host — an IP address or domain name." };
449	  }
450	  const port = input.sourcePort ?? 22;
451	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
452	    return { error: "SSH port must be between 1 and 65535." };
453	  }
454	  const sourceUser = (input.sourceUser ?? "root").trim();
455	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
456	    return { error: "Enter the SSH username on the source server." };
457	  }
458	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
459	    return { error: "Enter the SSH password for the source server." };
460	  }
461	
462	  await db.auditLog.create({
463	    data: { userId: user.id, action: "migration.scan", detail: `${sourceUser}@${host}:${port}` },
464	  }).catch(() => {});
465	
466	  // SANDBOX: never touch the outside world — hand back synthetic detection.
467	  if (SANDBOX) {
468	    return { scan: syntheticScan({ dbPassword: input.dbPassword }) };
469	  }
470	
471	  // Hard overall timeout so a slow/hostile source can't hang the request.
472	  const HARD_TIMEOUT_MS = 90_000;
473	  try {
474	    const scan = await Promise.race<ScanResult>([
475	      detectSource({
476	        host,
477	        port,
478	        user: sourceUser,
479	        password: input.sourcePassword,
480	        dbUser: input.dbUser?.trim() || undefined,
481	        dbPassword: input.dbPassword || undefined,
482	      }),
483	      new Promise<ScanResult>((_, reject) =>
484	        setTimeout(() => reject(new Error("Scan timed out — the source server took too long to respond.")), HARD_TIMEOUT_MS)
485	      ),
486	    ]);
487	    return { scan };
488	  } catch (e: any) {
489	    const msg = `${e?.message ?? e}`;
490	    // Map the common connection failures to friendly, non-leaky copy.
491	    if (/authentication|denied|password/i.test(msg)) {
492	      return { error: "Couldn't sign in to the source server — check the SSH username and password." };
493	    }
494	    if (/ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENOTFOUND|timed out|getaddrinfo/i.test(msg)) {
495	      return { error: "Couldn't reach the source server — check the host and SSH port." };
496	    }
497	    return { error: "We couldn't scan that server. Double-check the details and try again." };
498	  }
499	}
