501	// ---- Target free-space + OS probe (storage & compatibility guardrails) ------
502	
503	export type TargetInfo = {
504	  /** null when the server is unreachable / df couldn't be parsed → soft warning. */
505	  disk: { totalBytes: number; usedBytes: number; availBytes: number } | null;
506	  os: { id: string; versionId: string; pretty: string } | null;
507	  arch: string | null;
508	};
509	
510	/**
511	 * Probe a destination Nxeon server (owner-only) for its root-filesystem free
512	 * space and OS/architecture, so the wizard can show the storage headroom and the
513	 * OS-compatibility guardrail. Read-only: `df -B1`, `uname -m`, and a grep of
514	 * `/etc/os-release`. In SANDBOX returns synthetic values (never opens SSH).
515	 *
516	 * Failure is graceful: if the server is unreachable or df can't be parsed we
517	 * return `disk: null` (the UI shows "couldn't read free space" and allows the
518	 * migration with a soft warning rather than a hard block). OS falls back to the
519	 * server's known OS template; arch defaults to x86_64 (all our VMs are x86_64).
520	 */
521	export async function targetDiskFree(
522	  serverId: string
523	): Promise<{ error?: string; info?: TargetInfo }> {
524	  const { server } = await ownedTargetServer(serverId);
525	
526	  // OS fallback from the known OS template (works even if the box is unreachable).
527	  const tmpl = await db.osTemplate
528	    .findUnique({ where: { id: server.osTemplateId }, select: { family: true, version: true, name: true } })
529	    .catch(() => null);
530	  const osFallback = tmpl
531	    ? {
532	        id: (tmpl.family || "linux").toLowerCase(),
533	        versionId: tmpl.version || "",
534	        pretty: `${tmpl.name}${tmpl.version ? ` ${tmpl.version}` : ""}`,
535	      }
536	    : null;
537	
538	  if (SANDBOX) {
539	    // Synthetic 80 GB disk with ~63 GB free, matching our default plan sizing.
540	    return {
541	      info: {
542	        disk: { totalBytes: 80 * GiB, usedBytes: 17 * GiB, availBytes: 63 * GiB },
543	        os: osFallback ?? { id: "ubuntu", versionId: "24.04", pretty: "Ubuntu 24.04 LTS" },
544	        arch: "x86_64",
545	      },
546	    };
547	  }
548	
549	  // Need dedicatedIp to compute the SSH connection target (dedicated → :22).
550	  const full = await db.server.findUnique({
551	    where: { id: server.id },
552	    include: { dedicatedIp: true },
553	  });
554	
555	  try {
556	    const info = await withServerSsh(full as any, async (conn) => {
557	      // Root filesystem size/used/avail in bytes.
558	      const dfr = await exec(
559	        conn,
560	        "df -B1 --output=size,used,avail / 2>/dev/null | tail -n1",
561	        QUICK_TIMEOUT_MS
562	      );
563	      const nums = (dfr.stdout || "").trim().split("\n").pop()?.trim().split(/\s+/).map(Number) ?? [];
564	      let disk: TargetInfo["disk"] = null;
565	      if (nums.length >= 3 && nums.slice(0, 3).every((n) => Number.isFinite(n) && n > 0)) {
566	        disk = { totalBytes: nums[0], usedBytes: nums[1], availBytes: nums[2] };
567	      }
568	      const un = await exec(conn, "uname -m 2>/dev/null", QUICK_TIMEOUT_MS).catch(() => ({ stdout: "" }) as any);
569	      const arch = ((un.stdout as string) || "").trim().replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32) || null;
570	      const osr = await exec(
571	        conn,
572	        "grep -E '^(ID|VERSION_ID|PRETTY_NAME)=' /etc/os-release 2>/dev/null || true",
573	        QUICK_TIMEOUT_MS
574	      ).catch(() => ({ stdout: "" }) as any);
575	      const os = parseOsRelease((osr.stdout as string) || "") ?? osFallback;
576	      return { disk, os, arch: arch ?? "x86_64" };
577	    });
578	    return { info };
579	  } catch {
580	    // Unreachable / probe error → soft warning (no hard block).
581	    return { info: { disk: null, os: osFallback, arch: "x86_64" } };
582	  }
583	}
