585	/** The current user's migrations, newest first, WITHOUT any decrypted secrets. */
586	export async function listMigrations(): Promise<MigrationRow[]> {
587	  const user = await requireUser();
588	  const rows = await db.migration.findMany({
589	    where: { userId: user.id },
590	    orderBy: { createdAt: "desc" },
591	  });
592	  const serverIds = [...new Set(rows.map((r) => r.serverId))];
