69	/** Parse a human size label ("1.2G", "340M", "220 MB") into bytes. Mirrors the
70	 *  server's parseSizeLabel — kept local so the client never imports the ssh2-laden
71	 *  detection module. */
72	function parseSize(label: string): number {
73	  const m = /^([\d.]+)\s*([KMGT]?)/i.exec((label ?? "").trim());
74	  if (!m) return 0;
75	  const n = parseFloat(m[1]);
76	  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
77	  return n * (mult[m[2].toUpperCase()] ?? 1);
