82	  if (!Number.isFinite(bytes) || bytes <= 0) return "0 MB";
83	  const g = bytes / GiB;
84	  if (g >= 1) return g >= 10 ? `${g.toFixed(0)} GB` : `${g.toFixed(1)} GB`;
85	  const mb = bytes / (1024 * 1024);
86	  return `${Math.max(1, Math.round(mb))} MB`;
87	}
