89	// ---- OS/architecture compatibility helpers --------------------------------
90	/** Collapse arch aliases so amd64≡x86_64 and arm64≡aarch64 compare equal. */
91	function normArch(a: string | null | undefined): string {
92	  const s = (a ?? "").toLowerCase();
93	  if (!s) return "";
94	  if (["x86_64", "amd64", "x64"].includes(s)) return "x86_64";
95	  if (["aarch64", "arm64"].includes(s)) return "arm64";
96	  if (s.startsWith("armv") || s === "armhf" || s === "arm") return "arm";
97	  if (["i386", "i686", "x86"].includes(s)) return "x86";
98	  return s;
99	}
