101	const FAMILY_IDS: Record<string, string[]> = {
102	  debian: ["debian", "ubuntu", "linuxmint", "pop", "raspbian", "devuan", "kali", "elementary", "zorin"],
103	  rhel: ["rhel", "centos", "almalinux", "rocky", "fedora", "ol", "oracle", "amzn", "scientific", "cloudlinux"],
104	  suse: ["opensuse", "opensuse-leap", "opensuse-tumbleweed", "sles", "suse"],
105	  arch: ["arch", "manjaro", "endeavouros"],
106	  alpine: ["alpine"],
107	};
108	const FAMILY_LABEL: Record<string, string> = {
109	  debian: "Debian / Ubuntu",
110	  rhel: "RHEL / CentOS / Alma / Rocky",
111	  suse: "openSUSE / SLES",
112	  arch: "Arch",
113	  alpine: "Alpine",
114	  other: "another",
115	};
116	/** Map an os-release ID (or an osTemplate family string) to a distro family key. */
117	function familyOf(id: string | null | undefined): string {
118	  const s = (id ?? "").toLowerCase();
119	  if (!s) return "";
120	  for (const [fam, ids] of Object.entries(FAMILY_IDS)) if (ids.includes(s)) return fam;
121	  return "other";
122	}
123	
124	/** Pick the closest OS template to the source distro: same family first (prefer a
125	 *  matching major version), else nothing. Returns the template or null. */
126	function closestOsTemplate(
127	  sourceId: string,
128	  sourceVersion: string,
129	  templates: OsTemplateOption[]
130	): OsTemplateOption | null {
131	  const fam = familyOf(sourceId);
132	  if (!fam || fam === "other") return null;
133	  const sameFamily = templates.filter((t) => familyOf(t.family) === fam);
134	  if (sameFamily.length === 0) return null;
135	  const srcMajor = (sourceVersion || "").split(".")[0];
136	  // Prefer an exact family + same-major-version match, else the same family.
137	  const exact = sameFamily.find((t) => (t.version || "").split(".")[0] === srcMajor && srcMajor);
138	  return exact ?? sameFamily[0];
139	}
