242	  const [targetInfo, setTargetInfo] = useState<TargetInfo | null | undefined>(undefined);
243	  const [webSel, setWebSel] = useState<Set<string>>(new Set());
244	  const [homeSel, setHomeSel] = useState<Set<string>>(new Set());
245	  const [appSel, setAppSel] = useState<Set<string>>(new Set());
246	  const [dockerSel, setDockerSel] = useState<Set<string>>(new Set());
247	  const [customPaths, setCustomPaths] = useState<string[]>([]);
248	  const [newPath, setNewPath] = useState("");
