250	  const hostValid = /^[a-zA-Z0-9.\-:[\]]+$/.test(host.trim()) && host.trim().length > 0;
251	  const portNum = Number(port);
252	  const portValid = Number.isInteger(portNum) && portNum >= 1 && portNum <= 65535;
253	  const canScan = hostValid && portValid && user.trim().length > 0 && password.length > 0;
254	
255	  async function runScan() {
256	    setError(null);
257	    setScanning(true);
258	    setTargetInfo(undefined);
259	    try {
260	      // Scan the source and probe the destination's free space in parallel.
261	      const [res, diskRes] = await Promise.all([
262	        scanSource({
263	          serverId,
264	          sourceHost: host.trim(),
265	          sourcePort: portNum,
266	          sourceUser: user.trim(),
267	          sourcePassword: password,
268	        }),
269	        targetDiskFree(serverId).catch(() => ({ info: undefined })),
270	      ]);
271	      if (res.error) {
272	        setError(res.error);
273	        return;
274	      }
275	      setTargetInfo(diskRes?.info ?? null);
276	      const s = res.scan!;
277	      setScan(s);
278	      // Pre-check everything we found — the customer just unchecks what they don't want.
279	      setWebSel(new Set(s.webRoots.map((w) => w.path)));
280	      setHomeSel(new Set(s.homes.map((h) => h.path)));
281	      setAppSel(new Set(s.appDirs.map((a) => a.path)));
282	      // Docker bind-mount host paths are the container's data — pre-check the copyable ones.
283	      setDockerSel(new Set(s.containers.flatMap((c) => c.mounts.filter(isCopyablePath))));
