305	    }
306	  }
307	
308	  const selectedPaths = useMemo(
309	    () => [...new Set([...webSel, ...homeSel, ...appSel, ...dockerSel, ...customPaths])],
310	    [webSel, homeSel, appSel, dockerSel, customPaths]
311	  );
312	  // Databases are auto-included whenever an engine is detected — no password, no
