323	    if (detectedEngines.includes("postgres")) list.push("PostgreSQL");
324	    if (scan.containers.length > 0) list.push("Docker + Compose");
325	    const procBlob = [
326	      ...scan.ports.map((p) => p.proc || ""),
327	      ...scan.services.map((s) => s.name || ""),
328	    ]
