331	    if (/nginx/.test(procBlob) || (!/apache|httpd/.test(procBlob) && scan.webRoots.length > 0)) list.push("nginx");
332	    if (/apache|httpd/.test(procBlob)) list.push("Apache");
333	    const rtBlob = [
334	      ...scan.appDirs.map((a) => a.runtime || ""),
335	      ...scan.ports.map((p) => p.proc || ""),
