/**
 * Parse a MySQL/MariaDB client `--version` banner into a variant + major.minor.
 * MariaDB banners contain the literal "MariaDB" (e.g. "...Distrib 10.11.6-MariaDB");
 * Oracle MySQL banners look like "mysql  Ver 8.0.36 for Linux". Returns
 * {variant:null,version:null} when the banner is empty/unrecognised.
 */
export function parseMysqlVersion(raw: string): { variant: "mysql" | "mariadb" | null; version: string | null } {
  const s = cleanText(raw, 200);
  if (!s) return { variant: null, version: null };
  if (/mariadb/i.test(s)) {
    const m = /(\d+\.\d+)(?:\.\d+)?-MariaDB/i.exec(s) || /(\d+\.\d+)/.exec(s);
    return { variant: "mariadb", version: m ? m[1] : null };
  }
  const m = /Ver\s+(\d+\.\d+)/i.exec(s) || /(\d+\.\d+)/.exec(s);
  return { variant: "mysql", version: m ? m[1] : null };
}

/** Parse a `psql --version` / `pg_config --version` banner into a major version.
 *  PostgreSQL ≥ 10 uses a single-number major ("15"); 9.x keeps major.minor. */
export function parsePgVersion(raw: string): string | null {
  const s = cleanText(raw, 200);
  const m = /(\d+(?:\.\d+)?)/.exec(s);
  if (!m) return null;
  const major = parseInt(m[1], 10);
  return Number.isFinite(major) && major >= 10 ? String(major) : m[1];
}

